{"text":"[Reading 29 lines from start (total: 29 lines, 0 remaining)]\n\n\n\"\"\"\nAgentic Learning / Self-play Worker\nให้ AI 2 ตัวคุยกัน สอนกันเอง หรือใช้ tool แล้วเรียนรู้จากผลลัพธ์\n\"\"\"\nclass AgenticSelfPlayWorker:\n    def __init__(self):\n        self.agent_a = {\"name\": \"BullAgent\", \"winrate\": 0.52}\n        self.agent_b = {\"name\": \"BearAgent\", \"winrate\": 0.48}\n        \n    def self_play_round(self):\n        # Agent A vs B เทรดแข่งกัน\n        import random\n        winner = random.choice([\"A\",\"B\"])\n        if winner==\"A\":\n            self.agent_a[\"winrate\"] += 0.01\n            self.agent_b[\"winrate\"] -= 0.01\n        else:\n            self.agent_b[\"winrate\"] += 0.01\n            self.agent_a[\"winrate\"] -= 0.01\n        \n        print(f\"⚔️ Self-play - {self.agent_a['name']} {self.agent_a['winrate']:.0%} vs {self.agent_b['name']} {self.agent_b['winrate']:.0%} - Winner: {winner}\")\n        # สอนกันเอง\n        return {\"winner\": winner, \"a\": self.agent_a[\"winrate\"], \"b\": self.agent_b[\"winrate\"]}\n\nif __name__ == \"__main__\":\n    worker = AgenticSelfPlayWorker()\n    for _ in range(5):\n        worker.self_play_round()\n\n[executed on device: 10_3_6_9 (85294689-03d5-431e-abd5-9e27d4c94814)]"}